insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('IN', 'default', 'Indian reference chart of accounts (Schedule III)', '{}'::jsonb, true, 'companies', array['IN-SCH3-BS', 'IN-SCH3-PL']::text[], null, 'No statute of India prescribes a chart of accounts for a company. What is prescribed is the form of the financial statements: section 129(1) of the Companies Act, 2013 requires them to be in the form Schedule III provides, and Division I of that Schedule is the form for a company that applies the Accounting Standards rather than Ind AS. This chart is original. It follows the ledger-and-group convention Indian bookkeeping software shares — sundry debtors and creditors, input and output CGST, SGST/UTGST and IGST held apart, duties and taxes under current liabilities — and every block of codes is cut so that it reaches exactly one line of the two Schedule III statements this pack carries. The labels are English, the language Schedule III and the GST forms are printed in for a company; no official chart exists in Hindi or in any other language of the Eighth Schedule to transcribe, so the pack declares no second language.', 'schedule-iii')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

