insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('IN', 'IN-P-12-INTER', 'Purchase from another State — IGST 12 %, input tax credit', '{}'::jsonb, 'Integrated tax charged by a supplier registered in another State, credited in full', 'percent', 12, 'purchase', 'domestic', date '2017-07-01', date '2025-09-21', 'Section 7 of the Integrated Goods and Services Tax Act: a supply where the location of the supplier and the place of supply are in two different States, two Union territories or a State and a Union territory is an inter-State supply, and section 5(1) of the same Act levies the integrated tax on it at the whole rate, collected by the Centre alone. `applies_when.supply_vs_seller: other` is section 7 in the vocabulary of the core: the place of supply lies outside the State of the seller''s registration. The rate: Schedule II of Notification No. 1/2017-Integrated Tax (Rate) and of the Central Tax (Rate) notification of the same number, 28 June 2017. Notification No. 9/2025 superseded both with effect from 22 September 2025 and carries no schedule at 12 %: the goods it held were moved to 5 % or to 18 %, which is why this code closes on 21 September 2025. It stays in the pack so that a supply invoiced before that day keeps its code. Credit of the integrated tax under section 16(1) of the Central Goods and Services Tax Act, on the conditions of section 16(2), declared in column 2 of Table 4(A)(5) of FORM GSTR-3B.', null, null, 160, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cgst-s16', null, null, null, 'other'),
  ('IN', 'IN-P-12-INTRA', 'Purchase within the State — GST 12 % (CGST 6 % + SGST/UTGST 6 %), input tax credit', '{}'::jsonb, 'Both halves credited, each to its own ledger and its own column of Table 4', 'percent', 12, 'purchase', 'domestic', date '2017-07-01', date '2025-09-21', 'Section 8 of the Integrated Goods and Services Tax Act: a supply where the location of the supplier and the place of supply are in the same State or the same Union territory is an intra-State supply, and on it section 9(1) of the Central Goods and Services Tax Act levies the central tax and the State Goods and Services Tax Act of that State (the Union Territory Goods and Services Tax Act, in a Union territory without a legislature) levies the State or Union territory tax, each at half the rate — the Central Tax (Rate) notification and each State''s own notification print the same schedules at half the integrated rate. One code carries the whole rate and its postings split it: half to the central tax account and to the Central Tax column of the line, half to the State/UT tax account and to the State/UT Tax column. `applies_when.supply_vs_seller: same` is section 8 in the vocabulary of the core: the place of supply lies in the State the seller is registered in, which is the State of its GSTIN, so the company''s own territory has to be set to that State. The rate: Schedule II of Notification No. 1/2017-Integrated Tax (Rate) and of the Central Tax (Rate) notification of the same number, 28 June 2017. Notification No. 9/2025 superseded both with effect from 22 September 2025 and carries no schedule at 12 %: the goods it held were moved to 5 % or to 18 %, which is why this code closes on 21 September 2025. It stays in the pack so that a supply invoiced before that day keeps its code. Section 16(1) of the Central Goods and Services Tax Act entitles a registered person to credit of the input tax charged on a supply used in the course or furtherance of business, subject to the conditions of section 16(2) — a tax invoice, the supplier having reported it in FORM GSTR-1 so that it reaches the recipient''s FORM GSTR-2B, the goods or services received, the tax paid to the Government. The credit is declared in Table 4(A)(5), “All other ITC”, of FORM GSTR-3B, the central half in column 3 and the State half in column 4; the base of a taxable purchase reaches no box, because the form has none for it.', null, null, 150, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cgst-s16', null, null, null, 'same'),
  ('IN', 'IN-P-18-INTER', 'Purchase from another State — IGST 18 %, input tax credit', '{}'::jsonb, 'Integrated tax charged by a supplier registered in another State, credited in full', 'percent', 18, 'purchase', 'domestic', date '2017-07-01', null, 'Section 7 of the Integrated Goods and Services Tax Act: a supply where the location of the supplier and the place of supply are in two different States, two Union territories or a State and a Union territory is an inter-State supply, and section 5(1) of the same Act levies the integrated tax on it at the whole rate, collected by the Centre alone. `applies_when.supply_vs_seller: other` is section 7 in the vocabulary of the core: the place of supply lies outside the State of the seller''s registration. The rate: Schedule II of Notification No. 9/2025-Integrated Tax (Rate) and of the Central Tax (Rate) notification of the same number, 17 September 2025, in force from 22 September 2025, whose entry 639 also makes 18 % the rate of any goods no other schedule names; the rate stood at 18 % under Schedule III of Notification No. 1/2017 as well. Most services are taxed at the same rate under Notification No. 11/2017-Central Tax (Rate). Credit of the integrated tax under section 16(1) of the Central Goods and Services Tax Act, on the conditions of section 16(2), declared in column 2 of Table 4(A)(5) of FORM GSTR-3B.', null, null, 180, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cgst-s16', null, null, null, 'other'),
  ('IN', 'IN-P-18-INTER-BLOCKED', 'Purchase from another State — IGST 18 %, credit blocked by section 17(5)', '{}'::jsonb, 'The tax is a cost; shown in Table 4(A)(5) and reversed in Table 4(B)(1)', 'percent', 18, 'purchase', 'domestic', date '2017-07-01', null, 'Section 17(5) of the Central Goods and Services Tax Act: notwithstanding section 16(1), no input tax credit is available on the supplies it lists — among them motor vehicles for the transport of persons of up to thirteen seats and their repair, maintenance and insurance under clauses (a) and (ab), food and beverages, outdoor catering, beauty treatment, health services and club memberships under clause (b), works contract services for immovable property under clauses (c) and (d), and goods or services used for personal consumption under clause (g). The tax is charged by the supplier all the same, so it is part of what the thing cost: a `tax_on_base` posting puts the whole of it on the account of the line. Since the change of Table 4 in September 2022 the form asks for such credit to be shown in Table 4(A) and reversed in Table 4(B)(1), “As per rules 38, 42 & 43 of CGST Rules and section 17(5)”, so that the net credit of Table 4(C) excludes it: a pair of `tax` postings on the input account, one in and one straight back out, prints the amount in both rows and leaves the account where it was, and 4(C) is 4(A) less 4(B). Section 7 of the Integrated Goods and Services Tax Act: a supply where the location of the supplier and the place of supply are in two different States, two Union territories or a State and a Union territory is an inter-State supply, and section 5(1) of the same Act levies the integrated tax on it at the whole rate, collected by the Centre alone. `applies_when.supply_vs_seller: other` is section 7 in the vocabulary of the core: the place of supply lies outside the State of the seller''s registration. The rate: Schedule II of Notification No. 9/2025-Integrated Tax (Rate).', null, null, 260, 'gst', false, '{}'::tax_condition[], null, false, false, null, 'cgst-s17', null, null, null, 'other'),
  ('IN', 'IN-P-18-INTRA', 'Purchase within the State — GST 18 % (CGST 9 % + SGST/UTGST 9 %), input tax credit', '{}'::jsonb, 'Both halves credited, each to its own ledger and its own column of Table 4', 'percent', 18, 'purchase', 'domestic', date '2017-07-01', null, 'Section 8 of the Integrated Goods and Services Tax Act: a supply where the location of the supplier and the place of supply are in the same State or the same Union territory is an intra-State supply, and on it section 9(1) of the Central Goods and Services Tax Act levies the central tax and the State Goods and Services Tax Act of that State (the Union Territory Goods and Services Tax Act, in a Union territory without a legislature) levies the State or Union territory tax, each at half the rate — the Central Tax (Rate) notification and each State''s own notification print the same schedules at half the integrated rate. One code carries the whole rate and its postings split it: half to the central tax account and to the Central Tax column of the line, half to the State/UT tax account and to the State/UT Tax column. `applies_when.supply_vs_seller: same` is section 8 in the vocabulary of the core: the place of supply lies in the State the seller is registered in, which is the State of its GSTIN, so the company''s own territory has to be set to that State. The rate: Schedule II of Notification No. 9/2025-Integrated Tax (Rate) and of the Central Tax (Rate) notification of the same number, 17 September 2025, in force from 22 September 2025, whose entry 639 also makes 18 % the rate of any goods no other schedule names; the rate stood at 18 % under Schedule III of Notification No. 1/2017 as well. Most services are taxed at the same rate under Notification No. 11/2017-Central Tax (Rate). Section 16(1) of the Central Goods and Services Tax Act entitles a registered person to credit of the input tax charged on a supply used in the course or furtherance of business, subject to the conditions of section 16(2) — a tax invoice, the supplier having reported it in FORM GSTR-1 so that it reaches the recipient''s FORM GSTR-2B, the goods or services received, the tax paid to the Government. The credit is declared in Table 4(A)(5), “All other ITC”, of FORM GSTR-3B, the central half in column 3 and the State half in column 4; the base of a taxable purchase reaches no box, because the form has none for it.', null, null, 170, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cgst-s16', null, null, null, 'same'),
  ('IN', 'IN-P-18-INTRA-BLOCKED', 'Purchase within the State — GST 18 %, credit blocked by section 17(5)', '{}'::jsonb, 'The tax is a cost; shown in Table 4(A)(5) and reversed in Table 4(B)(1)', 'percent', 18, 'purchase', 'domestic', date '2017-07-01', null, 'Section 17(5) of the Central Goods and Services Tax Act: notwithstanding section 16(1), no input tax credit is available on the supplies it lists — among them motor vehicles for the transport of persons of up to thirteen seats and their repair, maintenance and insurance under clauses (a) and (ab), food and beverages, outdoor catering, beauty treatment, health services and club memberships under clause (b), works contract services for immovable property under clauses (c) and (d), and goods or services used for personal consumption under clause (g). The tax is charged by the supplier all the same, so it is part of what the thing cost: a `tax_on_base` posting puts the whole of it on the account of the line. Since the change of Table 4 in September 2022 the form asks for such credit to be shown in Table 4(A) and reversed in Table 4(B)(1), “As per rules 38, 42 & 43 of CGST Rules and section 17(5)”, so that the net credit of Table 4(C) excludes it: a pair of `tax` postings on the input account, one in and one straight back out, prints the amount in both rows and leaves the account where it was, and 4(C) is 4(A) less 4(B). Section 8 of the Integrated Goods and Services Tax Act: a supply where the location of the supplier and the place of supply are in the same State or the same Union territory is an intra-State supply, and on it section 9(1) of the Central Goods and Services Tax Act levies the central tax and the State Goods and Services Tax Act of that State (the Union Territory Goods and Services Tax Act, in a Union territory without a legislature) levies the State or Union territory tax, each at half the rate — the Central Tax (Rate) notification and each State''s own notification print the same schedules at half the integrated rate. One code carries the whole rate and its postings split it: half to the central tax account and to the Central Tax column of the line, half to the State/UT tax account and to the State/UT Tax column. `applies_when.supply_vs_seller: same` is section 8 in the vocabulary of the core: the place of supply lies in the State the seller is registered in, which is the State of its GSTIN, so the company''s own territory has to be set to that State. The rate: Schedule II of Notification No. 9/2025-Central Tax (Rate).', null, null, 250, 'gst', false, '{}'::tax_condition[], null, false, false, null, 'cgst-s17', null, null, null, 'same'),
  ('IN', 'IN-P-28-INTER', 'Purchase from another State — IGST 28 %, input tax credit', '{}'::jsonb, 'Integrated tax charged by a supplier registered in another State, credited in full', 'percent', 28, 'purchase', 'domestic', date '2017-07-01', date '2026-01-31', 'Section 7 of the Integrated Goods and Services Tax Act: a supply where the location of the supplier and the place of supply are in two different States, two Union territories or a State and a Union territory is an inter-State supply, and section 5(1) of the same Act levies the integrated tax on it at the whole rate, collected by the Centre alone. `applies_when.supply_vs_seller: other` is section 7 in the vocabulary of the core: the place of supply lies outside the State of the seller''s registration. The rate: Schedule VII of Notification No. 9/2025-Integrated Tax (Rate), 17 September 2025, which kept 28 % for pan masala and tobacco products only (the 2017 notification had it as Schedule IV and reached far more goods). The Government moved those goods to 40 % and ended the compensation cess on them from 1 February 2026, when an additional excise duty and a Health and National Security Cess took the cess''s place, so this code closes on 31 January 2026. Credit of the integrated tax under section 16(1) of the Central Goods and Services Tax Act, on the conditions of section 16(2), declared in column 2 of Table 4(A)(5) of FORM GSTR-3B.', null, null, 200, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cgst-s16', null, null, null, 'other'),
  ('IN', 'IN-P-28-INTRA', 'Purchase within the State — GST 28 % (CGST 14 % + SGST/UTGST 14 %), input tax credit', '{}'::jsonb, 'Both halves credited, each to its own ledger and its own column of Table 4', 'percent', 28, 'purchase', 'domestic', date '2017-07-01', date '2026-01-31', 'Section 8 of the Integrated Goods and Services Tax Act: a supply where the location of the supplier and the place of supply are in the same State or the same Union territory is an intra-State supply, and on it section 9(1) of the Central Goods and Services Tax Act levies the central tax and the State Goods and Services Tax Act of that State (the Union Territory Goods and Services Tax Act, in a Union territory without a legislature) levies the State or Union territory tax, each at half the rate — the Central Tax (Rate) notification and each State''s own notification print the same schedules at half the integrated rate. One code carries the whole rate and its postings split it: half to the central tax account and to the Central Tax column of the line, half to the State/UT tax account and to the State/UT Tax column. `applies_when.supply_vs_seller: same` is section 8 in the vocabulary of the core: the place of supply lies in the State the seller is registered in, which is the State of its GSTIN, so the company''s own territory has to be set to that State. The rate: Schedule VII of Notification No. 9/2025-Integrated Tax (Rate), 17 September 2025, which kept 28 % for pan masala and tobacco products only (the 2017 notification had it as Schedule IV and reached far more goods). The Government moved those goods to 40 % and ended the compensation cess on them from 1 February 2026, when an additional excise duty and a Health and National Security Cess took the cess''s place, so this code closes on 31 January 2026. Section 16(1) of the Central Goods and Services Tax Act entitles a registered person to credit of the input tax charged on a supply used in the course or furtherance of business, subject to the conditions of section 16(2) — a tax invoice, the supplier having reported it in FORM GSTR-1 so that it reaches the recipient''s FORM GSTR-2B, the goods or services received, the tax paid to the Government. The credit is declared in Table 4(A)(5), “All other ITC”, of FORM GSTR-3B, the central half in column 3 and the State half in column 4; the base of a taxable purchase reaches no box, because the form has none for it.', null, null, 190, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cgst-s16', null, null, null, 'same'),
  ('IN', 'IN-P-3-INTER', 'Purchase from another State — IGST 3 %, input tax credit', '{}'::jsonb, 'Integrated tax charged by a supplier registered in another State, credited in full', 'percent', 3, 'purchase', 'domestic', date '2017-07-01', null, 'Section 7 of the Integrated Goods and Services Tax Act: a supply where the location of the supplier and the place of supply are in two different States, two Union territories or a State and a Union territory is an inter-State supply, and section 5(1) of the same Act levies the integrated tax on it at the whole rate, collected by the Centre alone. `applies_when.supply_vs_seller: other` is section 7 in the vocabulary of the core: the place of supply lies outside the State of the seller''s registration. The rate: Schedule IV of Notification No. 9/2025-Integrated Tax (Rate), 17 September 2025 — gold, silver, platinum and articles of jewellery; the rate stood at 3 % under Schedule V of Notification No. 1/2017 as well. Credit of the integrated tax under section 16(1) of the Central Goods and Services Tax Act, on the conditions of section 16(2), declared in column 2 of Table 4(A)(5) of FORM GSTR-3B.', null, null, 240, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cgst-s16', null, null, null, 'other'),
  ('IN', 'IN-P-3-INTRA', 'Purchase within the State — GST 3 % (CGST 1.5 % + SGST/UTGST 1.5 %), input tax credit', '{}'::jsonb, 'Both halves credited, each to its own ledger and its own column of Table 4', 'percent', 3, 'purchase', 'domestic', date '2017-07-01', null, 'Section 8 of the Integrated Goods and Services Tax Act: a supply where the location of the supplier and the place of supply are in the same State or the same Union territory is an intra-State supply, and on it section 9(1) of the Central Goods and Services Tax Act levies the central tax and the State Goods and Services Tax Act of that State (the Union Territory Goods and Services Tax Act, in a Union territory without a legislature) levies the State or Union territory tax, each at half the rate — the Central Tax (Rate) notification and each State''s own notification print the same schedules at half the integrated rate. One code carries the whole rate and its postings split it: half to the central tax account and to the Central Tax column of the line, half to the State/UT tax account and to the State/UT Tax column. `applies_when.supply_vs_seller: same` is section 8 in the vocabulary of the core: the place of supply lies in the State the seller is registered in, which is the State of its GSTIN, so the company''s own territory has to be set to that State. The rate: Schedule IV of Notification No. 9/2025-Integrated Tax (Rate), 17 September 2025 — gold, silver, platinum and articles of jewellery; the rate stood at 3 % under Schedule V of Notification No. 1/2017 as well. Section 16(1) of the Central Goods and Services Tax Act entitles a registered person to credit of the input tax charged on a supply used in the course or furtherance of business, subject to the conditions of section 16(2) — a tax invoice, the supplier having reported it in FORM GSTR-1 so that it reaches the recipient''s FORM GSTR-2B, the goods or services received, the tax paid to the Government. The credit is declared in Table 4(A)(5), “All other ITC”, of FORM GSTR-3B, the central half in column 3 and the State half in column 4; the base of a taxable purchase reaches no box, because the form has none for it.', null, null, 230, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cgst-s16', null, null, null, 'same'),
  ('IN', 'IN-P-40-INTER', 'Purchase from another State — IGST 40 %, input tax credit', '{}'::jsonb, 'Integrated tax charged by a supplier registered in another State, credited in full', 'percent', 40, 'purchase', 'domestic', date '2025-09-22', null, 'Section 7 of the Integrated Goods and Services Tax Act: a supply where the location of the supplier and the place of supply are in two different States, two Union territories or a State and a Union territory is an inter-State supply, and section 5(1) of the same Act levies the integrated tax on it at the whole rate, collected by the Centre alone. `applies_when.supply_vs_seller: other` is section 7 in the vocabulary of the core: the place of supply lies outside the State of the seller''s registration. The rate: Schedule III of Notification No. 9/2025-Integrated Tax (Rate) and of the Central Tax (Rate) notification of the same number, 17 September 2025, in force from 22 September 2025 — the rate the notification sets for the goods it lists there (aerated and caffeinated beverages, motor cars above the thresholds it prints, and from 1 February 2026 pan masala, cigarettes and manufactured tobacco other than biris). Sub-section (1) of section 5 of the Integrated Goods and Services Tax Act caps the integrated tax at forty per cent and sub-section (1) of section 9 of the Central Goods and Services Tax Act caps the central tax at twenty, which is this rate split in two. Credit of the integrated tax under section 16(1) of the Central Goods and Services Tax Act, on the conditions of section 16(2), declared in column 2 of Table 4(A)(5) of FORM GSTR-3B.', null, null, 220, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cgst-s16', null, null, null, 'other'),
  ('IN', 'IN-P-40-INTRA', 'Purchase within the State — GST 40 % (CGST 20 % + SGST/UTGST 20 %), input tax credit', '{}'::jsonb, 'Both halves credited, each to its own ledger and its own column of Table 4', 'percent', 40, 'purchase', 'domestic', date '2025-09-22', null, 'Section 8 of the Integrated Goods and Services Tax Act: a supply where the location of the supplier and the place of supply are in the same State or the same Union territory is an intra-State supply, and on it section 9(1) of the Central Goods and Services Tax Act levies the central tax and the State Goods and Services Tax Act of that State (the Union Territory Goods and Services Tax Act, in a Union territory without a legislature) levies the State or Union territory tax, each at half the rate — the Central Tax (Rate) notification and each State''s own notification print the same schedules at half the integrated rate. One code carries the whole rate and its postings split it: half to the central tax account and to the Central Tax column of the line, half to the State/UT tax account and to the State/UT Tax column. `applies_when.supply_vs_seller: same` is section 8 in the vocabulary of the core: the place of supply lies in the State the seller is registered in, which is the State of its GSTIN, so the company''s own territory has to be set to that State. The rate: Schedule III of Notification No. 9/2025-Integrated Tax (Rate) and of the Central Tax (Rate) notification of the same number, 17 September 2025, in force from 22 September 2025 — the rate the notification sets for the goods it lists there (aerated and caffeinated beverages, motor cars above the thresholds it prints, and from 1 February 2026 pan masala, cigarettes and manufactured tobacco other than biris). Sub-section (1) of section 5 of the Integrated Goods and Services Tax Act caps the integrated tax at forty per cent and sub-section (1) of section 9 of the Central Goods and Services Tax Act caps the central tax at twenty, which is this rate split in two. Section 16(1) of the Central Goods and Services Tax Act entitles a registered person to credit of the input tax charged on a supply used in the course or furtherance of business, subject to the conditions of section 16(2) — a tax invoice, the supplier having reported it in FORM GSTR-1 so that it reaches the recipient''s FORM GSTR-2B, the goods or services received, the tax paid to the Government. The credit is declared in Table 4(A)(5), “All other ITC”, of FORM GSTR-3B, the central half in column 3 and the State half in column 4; the base of a taxable purchase reaches no box, because the form has none for it.', null, null, 210, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cgst-s16', null, null, null, 'same'),
  ('IN', 'IN-P-5-INTER', 'Purchase from another State — IGST 5 %, input tax credit', '{}'::jsonb, 'Integrated tax charged by a supplier registered in another State, credited in full', 'percent', 5, 'purchase', 'domestic', date '2017-07-01', null, 'Section 7 of the Integrated Goods and Services Tax Act: a supply where the location of the supplier and the place of supply are in two different States, two Union territories or a State and a Union territory is an inter-State supply, and section 5(1) of the same Act levies the integrated tax on it at the whole rate, collected by the Centre alone. `applies_when.supply_vs_seller: other` is section 7 in the vocabulary of the core: the place of supply lies outside the State of the seller''s registration. The rate: Schedule I of Notification No. 9/2025-Integrated Tax (Rate) and of the Central Tax (Rate) notification of the same number, both of 17 September 2025 and in force from 22 September 2025, which superseded Notification No. 1/2017 of 28 June 2017; the rate stood at 5 % under the 2017 notification as well. Services at the same rate are those of Notification No. 11/2017-Central Tax (Rate), as amended with effect from the same day. Credit of the integrated tax under section 16(1) of the Central Goods and Services Tax Act, on the conditions of section 16(2), declared in column 2 of Table 4(A)(5) of FORM GSTR-3B.', null, null, 140, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cgst-s16', null, null, null, 'other'),
  ('IN', 'IN-P-5-INTRA', 'Purchase within the State — GST 5 % (CGST 2.5 % + SGST/UTGST 2.5 %), input tax credit', '{}'::jsonb, 'Both halves credited, each to its own ledger and its own column of Table 4', 'percent', 5, 'purchase', 'domestic', date '2017-07-01', null, 'Section 8 of the Integrated Goods and Services Tax Act: a supply where the location of the supplier and the place of supply are in the same State or the same Union territory is an intra-State supply, and on it section 9(1) of the Central Goods and Services Tax Act levies the central tax and the State Goods and Services Tax Act of that State (the Union Territory Goods and Services Tax Act, in a Union territory without a legislature) levies the State or Union territory tax, each at half the rate — the Central Tax (Rate) notification and each State''s own notification print the same schedules at half the integrated rate. One code carries the whole rate and its postings split it: half to the central tax account and to the Central Tax column of the line, half to the State/UT tax account and to the State/UT Tax column. `applies_when.supply_vs_seller: same` is section 8 in the vocabulary of the core: the place of supply lies in the State the seller is registered in, which is the State of its GSTIN, so the company''s own territory has to be set to that State. The rate: Schedule I of Notification No. 9/2025-Integrated Tax (Rate) and of the Central Tax (Rate) notification of the same number, both of 17 September 2025 and in force from 22 September 2025, which superseded Notification No. 1/2017 of 28 June 2017; the rate stood at 5 % under the 2017 notification as well. Services at the same rate are those of Notification No. 11/2017-Central Tax (Rate), as amended with effect from the same day. Section 16(1) of the Central Goods and Services Tax Act entitles a registered person to credit of the input tax charged on a supply used in the course or furtherance of business, subject to the conditions of section 16(2) — a tax invoice, the supplier having reported it in FORM GSTR-1 so that it reaches the recipient''s FORM GSTR-2B, the goods or services received, the tax paid to the Government. The credit is declared in Table 4(A)(5), “All other ITC”, of FORM GSTR-3B, the central half in column 3 and the State half in column 4; the base of a taxable purchase reaches no box, because the form has none for it.', null, null, 130, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cgst-s16', null, null, null, 'same'),
  ('IN', 'IN-P-EXEMPT-INTER', 'Purchase from another State — exempt, nil-rated or from a composition supplier', '{}'::jsonb, null, 'percent', 0, 'purchase', 'exempt', date '2017-07-01', null, 'An inward supply on which no tax is charged because it is exempt under section 11 of the Central Goods and Services Tax Act, taxed at nil, or made by a supplier paying tax under the composition levy of section 10, who may not collect tax from the recipient. Table 5 of FORM GSTR-3B, “Values of exempt, nil-rated and non-GST inward supplies”, asks for them in two columns, inter-State and intra-State, and in two rows — “From a supplier under composition scheme, Exempt and Nil rated supply” and “Non GST supply”. This code is the inter-State column: seller and place of supply in different States.', null, null, 390, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'gstr-3b-form', null, null, null, 'other'),
  ('IN', 'IN-P-EXEMPT-INTRA', 'Purchase within the State — exempt, nil-rated or from a composition supplier', '{}'::jsonb, null, 'percent', 0, 'purchase', 'exempt', date '2017-07-01', null, 'An inward supply on which no tax is charged because it is exempt under section 11 of the Central Goods and Services Tax Act, taxed at nil, or made by a supplier paying tax under the composition levy of section 10, who may not collect tax from the recipient. Table 5 of FORM GSTR-3B, “Values of exempt, nil-rated and non-GST inward supplies”, asks for them in two columns, inter-State and intra-State, and in two rows — “From a supplier under composition scheme, Exempt and Nil rated supply” and “Non GST supply”. This code is the intra-State column: seller and place of supply in the same State.', null, null, 380, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'gstr-3b-form', null, null, null, 'same'),
  ('IN', 'IN-P-IMPORT-GOODS-18', 'Import of goods — IGST 18 % paid at customs', '{}'::jsonb, 'Assessed on the bill of entry and not on the supplier''s invoice', 'percent', 18, 'purchase', 'import', date '2017-07-01', null, 'Section 5(1) of the Integrated Goods and Services Tax Act, first proviso: the integrated tax on goods imported into India is levied and collected under section 3 of the Customs Tariff Act, 1975, on the value determined under that Act, at the point when duties of customs are levied under section 12 of the Customs Act, 1962 — on the bill of entry, and by the customs authority, not by the foreign seller. Section 7(2) makes the import an inter-State supply until the goods cross the customs frontier. The credit is declared in column 2 of Table 4(A)(1), “Import of goods”, of FORM GSTR-3B. The tax posts to the credit account and, as a counterpart, to the account the customs payment clears, because the supplier''s invoice carries no tax: the base on this code must be the value customs assessed the tax on, which is the assessable value plus the basic customs duty and not the price on the invoice.', null, null, 370, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'igst-s5', null, null, null, null),
  ('IN', 'IN-P-IMPORT-GOODS-5', 'Import of goods — IGST 5 % paid at customs', '{}'::jsonb, 'Assessed on the bill of entry and not on the supplier''s invoice', 'percent', 5, 'purchase', 'import', date '2017-07-01', null, 'Section 5(1) of the Integrated Goods and Services Tax Act, first proviso: the integrated tax on goods imported into India is levied and collected under section 3 of the Customs Tariff Act, 1975, on the value determined under that Act, at the point when duties of customs are levied under section 12 of the Customs Act, 1962 — on the bill of entry, and by the customs authority, not by the foreign seller. Section 7(2) makes the import an inter-State supply until the goods cross the customs frontier. The credit is declared in column 2 of Table 4(A)(1), “Import of goods”, of FORM GSTR-3B. The tax posts to the credit account and, as a counterpart, to the account the customs payment clears, because the supplier''s invoice carries no tax: the base on this code must be the value customs assessed the tax on, which is the assessable value plus the basic customs duty and not the price on the invoice.', null, null, 360, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'igst-s5', null, null, null, null),
  ('IN', 'IN-P-IMPORT-SERVICES-18', 'Import of services — IGST 18 % under reverse charge', '{}'::jsonb, 'A service from a supplier outside India: the recipient owes the integrated tax and takes it back as credit', 'percent', 18, 'purchase', 'foreign_services_received', date '2017-07-01', null, 'Section 7(4) of the Integrated Goods and Services Tax Act makes a supply of services imported into India an inter-State supply, and section 5(3) with Notification No. 10/2017-Integrated Tax (Rate) makes the recipient in India of a service from a supplier located outside India pay the integrated tax on it on reverse charge. The value and the tax go to line 3.1(d) of FORM GSTR-3B and the credit to Table 4(A)(2), “Import of services”; the tax itself is paid in cash, for the reason section 49(4) and section 2(82) of the Central Goods and Services Tax Act give for every reverse charge. 18 % is the rate of most services under Notification No. 11/2017-Central Tax (Rate) and its integrated tax twin; a service taxed at another rate needs another code.', null, null, 350, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'igst-s5', null, null, null, null),
  ('IN', 'IN-P-NONGST-INTER', 'Purchase from another State — outside GST', '{}'::jsonb, null, 'percent', 0, 'purchase', 'not_subject', date '2017-07-01', null, 'An inward supply of alcoholic liquor for human consumption or of one of the five petroleum products section 9(2) of the Central Goods and Services Tax Act keeps outside the tax for now. Table 5 of FORM GSTR-3B, “Values of exempt, nil-rated and non-GST inward supplies”, asks for them in two columns, inter-State and intra-State, and in two rows — “From a supplier under composition scheme, Exempt and Nil rated supply” and “Non GST supply”. This code is the inter-State column: seller and place of supply in different States.', null, null, 410, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'gstr-3b-form', null, null, null, 'other'),
  ('IN', 'IN-P-NONGST-INTRA', 'Purchase within the State — outside GST', '{}'::jsonb, null, 'percent', 0, 'purchase', 'not_subject', date '2017-07-01', null, 'An inward supply of alcoholic liquor for human consumption or of one of the five petroleum products section 9(2) of the Central Goods and Services Tax Act keeps outside the tax for now. Table 5 of FORM GSTR-3B, “Values of exempt, nil-rated and non-GST inward supplies”, asks for them in two columns, inter-State and intra-State, and in two rows — “From a supplier under composition scheme, Exempt and Nil rated supply” and “Non GST supply”. This code is the intra-State column: seller and place of supply in the same State.', null, null, 400, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'gstr-3b-form', null, null, null, 'same'),
  ('IN', 'IN-P-RCM-18-INTER', 'Purchase from another State under reverse charge — IGST 18 %', '{}'::jsonb, 'The recipient owes the integrated tax and takes it back as credit', 'percent', 18, 'purchase', 'domestic_reverse_charge', date '2017-07-01', null, 'Section 9(3) of the Central Goods and Services Tax Act and section 5(3) of the Integrated Goods and Services Tax Act: for the categories of supply the Government notifies, the tax is paid by the recipient on reverse charge as if the recipient were the person liable. The categories are those of Notification No. 13/2017-Central Tax (Rate) for services — among them goods transport agency services, legal services of an advocate, services of a director to the company, sponsorship, security services and the renting of a residential dwelling to a registered person — and of Notification No. 4/2017-Central Tax (Rate) for goods; section 9(4) adds the supplies a notified class of registered persons receives from unregistered suppliers. The recipient declares the value and the tax on line 3.1(d) of FORM GSTR-3B, “Inward supplies (liable to reverse charge)”, pays that tax in cash — section 49(4) lets the electronic credit ledger pay only output tax, which section 2(82) defines to exclude tax payable on reverse charge — and takes the same tax back as credit in Table 4(A)(3), subject to section 16. Rule 46(p) of the Central Goods and Services Tax Rules requires the supplier''s invoice to say that the tax is payable on reverse charge. Section 7 of the Integrated Goods and Services Tax Act: a supply where the location of the supplier and the place of supply are in two different States, two Union territories or a State and a Union territory is an inter-State supply, and section 5(1) of the same Act levies the integrated tax on it at the whole rate, collected by the Centre alone. `applies_when.supply_vs_seller: other` is section 7 in the vocabulary of the core: the place of supply lies outside the State of the seller''s registration. ', null, null, 340, 'gst', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgst-s9', null, null, null, 'other'),
  ('IN', 'IN-P-RCM-18-INTRA', 'Purchase within the State under reverse charge — GST 18 % (CGST 9 % + SGST/UTGST 9 %)', '{}'::jsonb, 'The recipient owes both halves and takes them back as credit', 'percent', 18, 'purchase', 'domestic_reverse_charge', date '2017-07-01', null, 'Section 9(3) of the Central Goods and Services Tax Act and section 5(3) of the Integrated Goods and Services Tax Act: for the categories of supply the Government notifies, the tax is paid by the recipient on reverse charge as if the recipient were the person liable. The categories are those of Notification No. 13/2017-Central Tax (Rate) for services — among them goods transport agency services, legal services of an advocate, services of a director to the company, sponsorship, security services and the renting of a residential dwelling to a registered person — and of Notification No. 4/2017-Central Tax (Rate) for goods; section 9(4) adds the supplies a notified class of registered persons receives from unregistered suppliers. The recipient declares the value and the tax on line 3.1(d) of FORM GSTR-3B, “Inward supplies (liable to reverse charge)”, pays that tax in cash — section 49(4) lets the electronic credit ledger pay only output tax, which section 2(82) defines to exclude tax payable on reverse charge — and takes the same tax back as credit in Table 4(A)(3), subject to section 16. Rule 46(p) of the Central Goods and Services Tax Rules requires the supplier''s invoice to say that the tax is payable on reverse charge. Section 8 of the Integrated Goods and Services Tax Act: a supply where the location of the supplier and the place of supply are in the same State or the same Union territory is an intra-State supply, and on it section 9(1) of the Central Goods and Services Tax Act levies the central tax and the State Goods and Services Tax Act of that State (the Union Territory Goods and Services Tax Act, in a Union territory without a legislature) levies the State or Union territory tax, each at half the rate — the Central Tax (Rate) notification and each State''s own notification print the same schedules at half the integrated rate. One code carries the whole rate and its postings split it: half to the central tax account and to the Central Tax column of the line, half to the State/UT tax account and to the State/UT Tax column. `applies_when.supply_vs_seller: same` is section 8 in the vocabulary of the core: the place of supply lies in the State the seller is registered in, which is the State of its GSTIN, so the company''s own territory has to be set to that State. The rate is the one the supply would bear at the supplier''s: 18 % is Schedule I or II of the rate notification, and the rate of goods transport agency services where the transporter charges no tax is 5 %.', null, null, 330, 'gst', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgst-s9', null, null, null, 'same'),
  ('IN', 'IN-P-RCM-5-INTER', 'Purchase from another State under reverse charge — IGST 5 %', '{}'::jsonb, 'The recipient owes the integrated tax and takes it back as credit', 'percent', 5, 'purchase', 'domestic_reverse_charge', date '2017-07-01', null, 'Section 9(3) of the Central Goods and Services Tax Act and section 5(3) of the Integrated Goods and Services Tax Act: for the categories of supply the Government notifies, the tax is paid by the recipient on reverse charge as if the recipient were the person liable. The categories are those of Notification No. 13/2017-Central Tax (Rate) for services — among them goods transport agency services, legal services of an advocate, services of a director to the company, sponsorship, security services and the renting of a residential dwelling to a registered person — and of Notification No. 4/2017-Central Tax (Rate) for goods; section 9(4) adds the supplies a notified class of registered persons receives from unregistered suppliers. The recipient declares the value and the tax on line 3.1(d) of FORM GSTR-3B, “Inward supplies (liable to reverse charge)”, pays that tax in cash — section 49(4) lets the electronic credit ledger pay only output tax, which section 2(82) defines to exclude tax payable on reverse charge — and takes the same tax back as credit in Table 4(A)(3), subject to section 16. Rule 46(p) of the Central Goods and Services Tax Rules requires the supplier''s invoice to say that the tax is payable on reverse charge. Section 7 of the Integrated Goods and Services Tax Act: a supply where the location of the supplier and the place of supply are in two different States, two Union territories or a State and a Union territory is an inter-State supply, and section 5(1) of the same Act levies the integrated tax on it at the whole rate, collected by the Centre alone. `applies_when.supply_vs_seller: other` is section 7 in the vocabulary of the core: the place of supply lies outside the State of the seller''s registration. ', null, null, 320, 'gst', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgst-s9', null, null, null, 'other'),
