insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('IN', 'IN-GSTR-3B', 'FORM GSTR-3B — summary return of outward and inward supplies, input tax credit and tax paid', array['month', 'quarter']::declaration_period[], 'month'::declaration_period, date '2017-07-01', null, 'Section 39(1) of the Central Goods and Services Tax Act: every registered person other than an Input Service Distributor, a non-resident taxable person and a person paying tax under section 10, 51 or 52 furnishes a return of inward and outward supplies, input tax credit, tax payable and tax paid for every calendar month or part of it — the proviso lets the Government notify a class of registered persons who furnish it for every quarter. Rule 61(1) of the Central Goods and Services Tax Rules makes that return FORM GSTR-3B, furnished electronically through the common portal, for each month under clause (i) and for each quarter under clause (ii) for the class the proviso reaches: the Quarterly Return Monthly Payment scheme, open to a registered person whose aggregate turnover did not exceed five crore rupees in the preceding financial year, who pays the tax of each of the first two months of the quarter in FORM GST PMT-06 by the twenty-fifth day of the following month under rule 61(3). So the form is filed on two cadences, the monthly one is what the statute gives everybody who has not opted in, and that is `period_default`. The statement of outward supplies, FORM GSTR-1 of section 37 and rule 59, is a separate filing invoice by invoice, which this pack does not carry; the README says what it leaves out.', true,'day_of_month_after_period'::filing_deadline_rule, 20, null, 'Rule 61(1)(i) of the Central Goods and Services Tax Rules: FORM GSTR-3B for each month is furnished “on or before the twentieth day of the month succeeding such month”. A quarterly filer under rule 61(1)(ii) files on the twenty-second or the twenty-fourth day of the month after the quarter, according to the State of its principal place of business, which the Table of that clause lists — a second deadline this field cannot hold beside the first, and the README records it. Section 39(7) makes the tax due by the same last date as the return.', 'cgst-rule61', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('IN', 'IN-GSTR-3B', '31a', 'base', '3.1(a) Outward taxable supplies (other than zero rated, nil rated and exempted) — total taxable value', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'FORM GSTR-3B [See rule 61(5)], Table 3.1 “Details of Outward Supplies and inward supplies liable to reverse charge”, row (a), column 2 “Total Taxable value”. Instruction 1 of the form: value of invoices plus debit notes less credit notes, plus advances not yet invoiced and less advances adjusted — the last two are not carried by this pack.', 'gstr-3b-form'),
  ('IN', 'IN-GSTR-3B', '31aIGST', 'tax', '3.1(a) Outward taxable supplies — integrated tax', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'FORM GSTR-3B [See rule 61(5)], Table 3.1, row (a), column 3 “Integrated Tax”.', 'gstr-3b-form'),
  ('IN', 'IN-GSTR-3B', '31aCGST', 'tax', '3.1(a) Outward taxable supplies — central tax', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'FORM GSTR-3B [See rule 61(5)], Table 3.1, row (a), column 4 “Central Tax”.', 'gstr-3b-form'),
