  ('IN', 'IN-GSTR-3B', '31c', 'base', '3.1(c) Other outward supplies (nil rated, exempted) — total taxable value', '{}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'FORM GSTR-3B [See rule 61(5)], Table 3.1, row (c), column 2.', 'gstr-3b-form'),
  ('IN', 'IN-GSTR-3B', '31d', 'base', '3.1(d) Inward supplies (liable to reverse charge) — total taxable value', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'FORM GSTR-3B [See rule 61(5)], Table 3.1, row (d), column 2: the supplies on which the recipient pays the tax under section 9(3) or 9(4) of the Central Goods and Services Tax Act or section 5(3) or 5(4) of the Integrated Goods and Services Tax Act, the import of services included.', 'gstr-3b-form'),
  ('IN', 'IN-GSTR-3B', '31dIGST', 'tax', '3.1(d) Inward supplies liable to reverse charge — integrated tax', '{}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'FORM GSTR-3B [See rule 61(5)], Table 3.1, row (d), column 3.', 'gstr-3b-form'),
  ('IN', 'IN-GSTR-3B', '31dCGST', 'tax', '3.1(d) Inward supplies liable to reverse charge — central tax', '{}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'FORM GSTR-3B [See rule 61(5)], Table 3.1, row (d), column 4.', 'gstr-3b-form'),
