  plus_boxes      = excluded.plus_boxes,
  minus_boxes     = excluded.minus_boxes,
  rate            = excluded.rate,
  rate_of_box     = excluded.rate_of_box,
  floor_zero      = excluded.floor_zero,
  hidden          = excluded.hidden,
  xml_element     = excluded.xml_element,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('IN-SCH3-BS', 'IN', 'default', 'Balance Sheet — Schedule III, Division I', 'balance_sheet', 'Schedule III, Division I', date '1970-01-01', null, 'Section 129(1) of the Companies Act, 2013: the financial statements shall be in the form or forms provided for different classes of companies in Schedule III. Division I of Schedule III is the form for a company whose financial statements comply with the Companies (Accounting Standards) Rules, 2006 — the Accounting Standards, which a company not required to apply Ind AS reports under; Division II is the Ind AS form and is not carried. This is Part I, the Balance Sheet, line for line down to the sub-heads of the face of the statement, as amended with effect from 1 April 2021. The Notes the Schedule requires, the comparatives of the previous period and the rounding of general instruction 4 are the preparer''s and not the ledger''s.', 'schedule-iii'),
  ('IN-SCH3-PL', 'IN', 'default', 'Statement of Profit and Loss — Schedule III, Division I', 'income_statement', 'Schedule III, Division I', date '1970-01-01', null, 'Schedule III to the Companies Act, 2013, Division I, Part II — Statement of Profit and Loss, lines I to XV. Lines XII to XIV, profit and tax of discontinuing operations, and line XVI, earnings per share, are not carried: a ledger holds no discontinuing operation apart from the others and no share count, so line XV here is line XI of the Schedule. The 2021 amendment calls line III “Total Income”, the wording kept here.', 'schedule-iii')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

