update country_defaults set
  numbering_gapless             = true,
  number_format                 = '{CODE}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Rule 46(b) of the Central Goods and Services Tax Rules: a tax invoice carries “a consecutive serial number not exceeding sixteen characters, in one or multiple series, containing alphabets or numerals or special characters- hyphen or dash and slash … and any combination thereof, unique for a financial year”. Consecutive is `gapless`. Unique for a financial year is satisfied by a counter that never restarts, which is what this pack declares: the core restarts a `_per_year` counter on the calendar year, and an Indian financial year runs from April to March, so a restart in January would be the wrong restart. `{CODE}-{NNNN}` stays well inside sixteen characters; a series that restarts each April, the common Indian practice, is the preparer''s choice and not something the core can number yet.',
  numbering_source_key          = 'cgst-rule46',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_date',
  tax_point_legal_reference     = 'Section 12(2) of the Central Goods and Services Tax Act: the time of supply of goods is the earlier of the date of issue of the invoice, or the last date by which section 31 requires it to be issued, and the date on which the supplier receives the payment; section 13(2) says the same of services, with the date of provision of the service where the invoice is late. The payment branch no longer reaches goods — Notification No. 66/2017-Central Tax takes advances for goods out of it for a supplier outside the composition levy — and reaches services only through an advance, a document Ekwo has no concept of (docs/international.md records the limit). Section 31(1) requires the invoice of goods before or at their removal or delivery, and section 31(2) the invoice of services within the period rule 47 prescribes, so an invoiced supply takes its tax point from the invoice, which is what `invoice_date` says.',
  tax_point_source_key          = 'cgst-s12',
  posted_edit_policy            = 'reversal_only',
  posted_edit_policy_legal_reference = 'Section 34 of the Central Goods and Services Tax Act corrects a tax invoice by a credit note or a debit note that refers to it, and section 36 requires the accounts and records to be retained until seventy-two months after the due date of the annual return for the year. A posted document of an Indian company is therefore undone by a credit note that names it, and in no other way. Since 1 April 2023 rule 3(1) of the Companies (Accounts) Rules, 2014 also requires the accounting software of a company to keep an audit trail of every change that cannot be disabled, which is the same answer from the company-law side.',
  posted_edit_policy_source_key = 'cgst-s36',
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Electronic invoicing is obligatory in India above a turnover, and this pack leaves all four fields above empty for the reason packs/sa/, packs/mx/ and packs/vn/ leave them empty: it is a clearance regime, not an exchange between two parties'' access points, and `profile` names an EN 16931 profile a brick of packages/formats writes. The obligation: rule 48(4) of the Central Goods and Services Tax Rules makes the class of registered persons the Government notifies prepare their invoice with the particulars of FORM GST INV-01 after obtaining an Invoice Reference Number (IRN) by uploading it to the Invoice Registration Portal, and rule 48(5) says that an invoice such a person issues in any other manner “shall not be treated as an invoice”; rule 46(r) puts the QR code embedding the IRN on it. Notification No. 13/2020-Central Tax defines the class by aggregate turnover, and Notification No. 10/2023-Central Tax lowered the threshold to five crore rupees in any financial year from 2017-18 onwards with effect from 1 August 2023 — the threshold still in force at `released_at`. Government departments, Special Economic Zone units and a few sectors (insurers, banking companies, goods transport agencies, passenger transport, cinema admission) are outside it. The obligation covers invoices, credit notes and debit notes to registered persons and exports, not supplies to consumers. INV-01 is a JSON schema of the GST Network and not a PINT or an EN 16931 profile, and no brick of this repository writes it, signs it, talks to the Invoice Registration Portal or prints the QR code: a document issued from Ekwo by a company above the threshold is not an invoice in the sense of rule 48(5) until it has been registered elsewhere. `obligation` is left out because the schema refuses `mandatory` without `mandatory_from`, and `mandatory_from` without a `profile`. `party_scheme` and `vat_scheme` are empty: India has no ISO 6523 identifier scheme in the Peppol list; an Indian party is identified by its fifteen-character GSTIN, whose first two digits are the State code. docs/international.md carries the rest.',
  einvoice_source_key           = 'cgst-rule48',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = array['mt940', 'csv']::text[],
  payment_formats               = array['csv']::text[],
  fiscal_year_default           = 'april'
 where country = 'IN';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('IN', 'export_lut', 'export', 'SUPPLY MEANT FOR EXPORT/SUPPLY TO SEZ UNIT OR SEZ DEVELOPER FOR AUTHORISED OPERATIONS UNDER BOND OR LETTER OF UNDERTAKING WITHOUT PAYMENT OF INTEGRATED TAX', '{}'::jsonb, 10, date '1970-01-01', null, 'Rule 46 of the Central Goods and Services Tax Rules, proviso: in the case of the export of goods or services the invoice carries this endorsement where the supply is made under bond or Letter of Undertaking, and names the recipient, the address of delivery and the country of destination. The one export code of this pack is that supply.')
on conflict (country, code) do update set
